#!/bin/bash
# Builds the power HDI publisher (power/native_power_hdi_publisher.cpp) on the build PC: it hosts the donor's own
# power HDI implementation and registers it as power_interface_service, which powermgr suspends the device through.
# The HDI 1.3 C++ headers are generated by hdi-gen (as sensors/build-sensors.sh does) from OpenHarmony's power IDL
# (drivers_interface 83043df7, $HARMONY_BUILD/ohos/src-new, sparse checkout with power/ added).
# Output: $WORK/out-power/.
set -e
. "$(dirname "$0")/../../build/env.sh"
HB=${HARMONY_BUILD:-$HOME/harmony-build}
M2=$WORK
P=$COMMON/power
N=$HB/ohos/sdk/native
S=$HB/ohos/src
SN=$HB/ohos/src-new/drivers_interface
DONOR=$HB/donor/pura70proplus-7.0.0.107/mnt
O=$WORK/out-power
L=$O/link
G=$O/gen
mkdir -p $L
git -C $SN sparse-checkout add power
for f in system/system/lib64/chipset-sdk-sp/{libc++.so,libutils.z.so,libhdi.z.so,libhdi_base.z.so} \
         system/system/lib64/chipset-pub-sdk/{libipc_single.z.so,libipc_common.z.so}; do
    [ -f $L/$(basename $f) ] || sudo -n cat $DONOR/$f > $L/$(basename $f)
done

HG=$S/drivers_hdf_core/framework/tools/hdi-gen/hdi-gen
I=$O/idl/ohos/hdi/power
rm -rf $O/idl $G && mkdir -p $I $G
cp -r $SN/power/v1_0 $SN/power/v1_1 $SN/power/v1_2 $SN/power/v1_3 $I/
for f in $(cd $I && ls v1_*/*.idl); do
    $HG -s full -m ipc -l cpp -r ohos.hdi:$O/idl/ohos/hdi -c $I/$f -d $G
done

HDF=$S/drivers_hdf_core/interfaces/inner_api
INC="-I$G -I$G/power -I$HDF/hdi -I$HDF/ipc -I$HDF/hdi/base -I$HDF/utils -I$HDF/osal/uhdf -I$HDF/core
     -I$S/commonlibrary_c_utils/base/include -I$S/communication_ipc/interfaces/innerkits/ipc_core/include
     -I$S/communication_ipc/interfaces/innerkits/ipc_single/include -I$S/hiviewdfx_hilog/interfaces/native/innerkits/include"
CXX="$N/llvm/bin/clang++ --target=aarch64-linux-ohos --sysroot=$N/sysroot -O2 -Wall -Wextra -std=c++17
     -fno-exceptions -fno-rtti -nostdlib++ -include $COMMON/include/platform_cpp_config.h -fuse-ld=lld"
LIBS="$L/libhdi.z.so $L/libhdi_base.z.so $L/libutils.z.so $L/libipc_single.z.so $L/libipc_common.z.so $L/libc++.so
      -ldl -Wl,--allow-shlib-undefined"
$CXX $INC $P/native_power_hdi_publisher.cpp $LIBS -o $O/native_power_hdi_publisher
ls -l $O/native_power_hdi_publisher
